  ["    if v < n.Val {\n        n.Left = insert(n.___, v)\n    } else {\n        n.Right = insert(n.Right, v)\n    }\n    return n\n}\n"] = "    if v < n.Val {\n        n.Left = insert(n.___, v)\n    } else {\n        n.Right = insert(n.Right, v)\n    }\n    return n\n}\n",
  ["    let v = fib(n - 1, memo) + fib(n - 2, memo);\n    memo.___(n, v);        // remember it for next time\n    v\n}\n"] = "    let v = fib(n - 1, memo) + fib(n - 2, memo);\n    memo.___(n, v);        // 次回のために覚える\n    v\n}\n",
  ["    switch {\n    case a[mid] == x: return mid\n    case a[mid] < x:\n        lo = ___ + 1        // drop the left half\n    default:\n        hi = mid\n    }\n"] = "    switch {\n    case a[mid] == x: return mid\n    case a[mid] < x:\n        lo = ___ + 1        // 左半分を捨てる\n    default:\n        hi = mid\n    }\n",
  ["    while let Some(n) = q.pop_front() {\n        order.push(n);\n        for &m in &g[&n] {\n            // adds m; true only if it was not there yet\n            if seen.___(m) { q.push_back(m); }\n        }\n    }\n"] = "    while let Some(n) = q.pop_front() {\n        order.push(n);\n        for &m in &g[&n] {\n            // m を追加。まだ無かった時だけ true\n            if seen.___(m) { q.push_back(m); }\n        }\n    }\n",
  ['"18".parse::<i32>() is Ok(18). "1x8" is Err(ParseIntError). Ticket one closed.'] = '"18".parse::<i32>() は Ok(18)。"1x8" は Err(ParseIntError)。チケット1完了。',
  ['"Lucky Mac, cam ykcul" should pass: skip spaces and commas first. Which iterator adapter keeps only some items?'] = '"Lucky Mac, cam ykcul" は通るはず: まず空白とカンマを飛ばす。一部の要素だけ残すイテレータのアダプタは？',
  ['#[___(Debug)]\nstruct Order { qty: u32 }\n\nlet o = Order { qty: 2 };\nprintln!("{:?}", o);        // Order { qty: 2 }\n'] = '#[___(Debug)]\nstruct Order { qty: u32 }\n\nlet o = Order { qty: 2 };\nprintln!("{:?}", o);        // Order { qty: 2 }\n',
  ["#[derive(Clone, Debug)] generates the impls. Also common: PartialEq, Default, Copy for small types."] = "#[derive(Clone, Debug)] が impl を生成する。よく使うものに PartialEq、Default、小さな型なら Copy。",
  ["#[derive(Debug, Clone, PartialEq)] generates common traits. {:?} needs Debug. The till prints the order and the afternoon set is sold."] = "#[derive(Debug, Clone, PartialEq)] はよく使うトレイトを生成する。{:?} には Debug が要る。レジが注文を印字し、アフタヌーンセットが売れる。",
  ['#[derive(Default, Debug)]\nstruct Tray { buns: u32, teas: u32 }\n// An empty tray, all zeros, without typing them.\nlet empty = Tray::___();\nprintln!("{empty:?}");\n'] = '#[derive(Default, Debug)]\nstruct Tray { buns: u32, teas: u32 }\n// 全部ゼロの空トレイを、打ち込まずに。\nlet empty = Tray::___();\nprintln!("{empty:?}");\n',
  ['#[derive(Serialize, Deserialize)]\nstruct Order {\n    #[serde(___ = "dish")]\n    name: String,\n    qty: u32,\n}\n// {"dish":"toast","qty":2} now fills name\n'] = '#[derive(Serialize, Deserialize)]\nstruct Order {\n    #[serde(___ = "dish")]\n    name: String,\n    qty: u32,\n}\n// {"dish":"toast","qty":2} がこれで name に入る\n',
  ['#[derive(Serialize, Deserialize)]\nstruct Order {\n    name: String,\n    #[serde(___ = "Option::is_none")]\n    note: Option<String>,\n}\n// None -> {"name":"toast"}   Some -> {"name":..,"note":..}\n'] = '#[derive(Serialize, Deserialize)]\nstruct Order {\n    name: String,\n    #[serde(___ = "Option::is_none")]\n    note: Option<String>,\n}\n// None -> {"name":"toast"}   Some -> {"name":..,"note":..}\n',
  ['#[serde(rename = "dish")] is the Go json tag. rename_all = "camelCase" on the struct is common.'] = '#[serde(rename = "dish")] が Go の json タグに相当。構造体に rename_all = "camelCase" もよく使う。',
  ["#[tokio::main] builds the runtime and block_on(main()). Use #[tokio::test] in tests."] = "#[tokio::main] がランタイムを作って block_on(main()) する。テストでは #[tokio::test]。",
  ["$ cargo ___\n   Compiling delivery v0.1.0\nrunning 2 checks\nqty_parses ....... ok\neta_is_positive .. ok\nresult: ok. 2 passed; 0 failed\n"] = "$ cargo ___\n   Compiling delivery v0.1.0\nrunning 2 checks\nqty_parses ....... ok\neta_is_positive .. ok\nresult: ok. 2 passed; 0 failed\n",
  ['$ cargo ___\n$ git diff --stat\n src/main.rs | 14 ++++++-------\n$ cargo ___ --check && echo "clean"\n'] = '$ cargo ___\n$ git diff --stat\n src/main.rs | 14 ++++++-------\n$ cargo ___ --check && echo "clean"\n',
  ["$ cargo ___\nwarning: this `.into_iter()` call is equivalent to `.iter()`\n  --> src/main.rs:12:24\n   = help: consider using `.iter()`\n"] = "$ cargo ___\nwarning: this `.into_iter()` call is equivalent to `.iter()`\n  --> src/main.rs:12:24\n   = help: consider using `.iter()`\n",
  ["$ cargo ___ delivery\n     Created binary (application) `delivery` package\n$ ls delivery\nCargo.toml  src/main.rs\n"] = "$ cargo ___ delivery\n     Created binary (application) `delivery` package\n$ ls delivery\nCargo.toml  src/main.rs\n",
  ["$ cargo ___ reqwest --features json\n    Updating crates.io index\n      Adding reqwest v0.12 to dependencies\n"] = "$ cargo ___ reqwest --features json\n    Updating crates.io index\n      Adding reqwest v0.12 to dependencies\n",
  ["$ cargo build --___\n   Compiling delivery v0.1.0\n    Finished [optimized] target(s) in 41.2s\n"] = "$ cargo build --___\n   Compiling delivery v0.1.0\n    Finished [optimized] target(s) in 41.2s\n",
