  ['fn count(s: ___String) -> usize {\n    s.len()\n}\nlet a = String::from("coffee");\nlet n = count(&a);\nprintln!("{} {}", a, n);   // a still alive\n'] = 'fn count(s: ___String) -> usize {\n    s.len()\n}\nlet a = String::from("coffee");\nlet n = count(&a);\nprintln!("{} {}", a, n);   // a はまだ生きている\n',
  ['fn dfs(g: &Graph, start: u32, seen: &mut HashSet<u32>) {\n    let mut stack = vec![start];     // a Vec is a stack too\n    while let Some(n) = stack.___() { // LIFO: newest first\n        if !seen.insert(n) { continue; }\n        print!("{n} "); stack.extend(&g[&n]);\n    }\n}\n'] = 'fn dfs(g: &Graph, start: u32, seen: &mut HashSet<u32>) {\n    let mut stack = vec![start];     // Vec もスタック\n    while let Some(n) = stack.___() { // LIFO: 新しいものから\n        if !seen.insert(n) { continue; }\n        print!("{n} "); stack.extend(&g[&n]);\n    }\n}\n',
  ["fn discount(n: u32) -> u32 {\n    if n == 0 {\n        ___ 0;        // early exit, with a semicolon\n    }\n    n * 18 - 5\n}\n"] = "fn discount(n: u32) -> u32 {\n    if n == 0 {\n        ___ 0;        // 早期リターン、セミコロン付き\n    }\n    n * 18 - 5\n}\n",
  ["fn f<T: Bound> is checked at compile time. dyn Trait in a Box decides at run time."] = "fn f<T: Bound> はコンパイル時に検査される。Box の中の dyn Trait は実行時に決める。",
  ["fn fact(n: u64) -> u64 {\n    if n <= 1 {\n        1\n    } else {\n        n * fact(___)        // toward the base case\n    }\n}\n"] = "fn fact(n: u64) -> u64 {\n    if n <= 1 {\n        1\n    } else {\n        n * fact(___)        // 基底ケースへ向かう\n    }\n}\n",
  ["fn fact(n: u64) -> u64 {\n    if n <= 1 {\n        ___                  // base case\n    } else {\n        n * fact(n - 1)\n    }\n}\n"] = "fn fact(n: u64) -> u64 {\n    if n <= 1 {\n        ___                  // 基底ケース\n    } else {\n        n * fact(n - 1)\n    }\n}\n",
  ["fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {\n    if n < 2 {\n        return n;\n    }\n    if let Some(&v) = memo.___(&n) {   // seen before?\n        return v;\n    }\n"] = "fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {\n    if n < 2 {\n        return n;\n    }\n    if let Some(&v) = memo.___(&n) {   // 前に見た？\n        return v;\n    }\n",
  ["fn first_dish(order: &Order) -> Option<&str> {\n    // works on Option too, not only on Result\n    let dish = order.items.first()___;\n    Some(dish.as_str())\n}\n"] = "fn first_dish(order: &Order) -> Option<&str> {\n    // Result だけでなく Option にも使える\n    let dish = order.items.first()___;\n    Some(dish.as_str())\n}\n",
  ["fn greet() { } With no return type the function returns (), the empty tuple called unit."] = "fn greet() { } 戻り値の型がなければ、関数は () を返す。unit と呼ばれる空のタプルだ。",
  ['fn greet(name: ___) {\n    println!("hi {}", name);\n}\nlet owned = String::from("Alex");\ngreet("Mei");           // a literal\ngreet(&owned);          // a borrowed String also works\n'] = 'fn greet(name: ___) {\n    println!("hi {}", name);\n}\nlet owned = String::from("Alex");\ngreet("Mei");           // リテラル\ngreet(&owned);          // 借用した String でも動く\n',
  ["fn height(link: &Link) -> usize {\n    match link {\n        None => 0,\n        Some(n) => 1 + height(&n.left)\n            .___(height(&n.right)),   // taller side wins\n    }\n}\n"] = "fn height(link: &Link) -> usize {\n    match link {\n        None => 0,\n        Some(n) => 1 + height(&n.left)\n            .___(height(&n.right)),   // 高い方が勝つ\n    }\n}\n",
  ["fn hop(n: Option<&ListNode>) -> Option<&ListNode> {\n    n?.next.___()        // through the Box, by ref\n}\nlet (mut slow, mut fast) = (Some(head), Some(head));\nwhile hop(fast).is_some() {      // fast still has a next\n    fast = hop(hop(fast)); slow = hop(slow);\n}\n"] = "fn hop(n: Option<&ListNode>) -> Option<&ListNode> {\n    n?.next.___()        // Box を抜けて参照で\n}\nlet (mut slow, mut fast) = (Some(head), Some(head));\nwhile hop(fast).is_some() {      // fast にまだ next がある\n    fast = hop(hop(fast)); slow = hop(slow);\n}\n",
  ["fn inorder(link: &Link, out: &mut Vec<i32>) {\n    if let Some(n) = link {\n        inorder(&n.left, out);\n        out.push(n.val);           // the node itself\n        inorder(&n.___, out);\n    }\n}\n"] = "fn inorder(link: &Link, out: &mut Vec<i32>) {\n    if let Some(n) = link {\n        inorder(&n.left, out);\n        out.push(n.val);           // ノード自身\n        inorder(&n.___, out);\n    }\n}\n",
  ["fn insert(link: &mut Link, v: i32) {\n    match link {\n        None => *link = Some(Box::new(Node::leaf(v))),\n        Some(n) if v < n.val => insert(&mut n.___, v),\n        Some(n) => insert(&mut n.right, v),\n    }\n}\n"] = "fn insert(link: &mut Link, v: i32) {\n    match link {\n        None => *link = Some(Box::new(Node::leaf(v))),\n        Some(n) if v < n.val => insert(&mut n.___, v),\n        Some(n) => insert(&mut n.right, v),\n    }\n}\n",
  ["fn insert(link: &mut Link, v: i32) {\n    match link {\n        ___ => *link = Some(Box::new(Node::leaf(v))),\n        Some(n) if v < n.val => insert(&mut n.left, v),\n        Some(n) => insert(&mut n.right, v),\n    }\n}\n"] = "fn insert(link: &mut Link, v: i32) {\n    match link {\n        ___ => *link = Some(Box::new(Node::leaf(v))),\n        Some(n) if v < n.val => insert(&mut n.left, v),\n        Some(n) => insert(&mut n.right, v),\n    }\n}\n",
  ["fn is_anagram(a: &str, b: &str) -> bool {\n    let mut count = [0i32; ___];    // one slot per letter\n    for c in a.bytes() { count[(c - b'a') as usize] += 1; }\n    for c in b.bytes() { count[(c - b'a') as usize] -= 1; }\n    count.iter().all(|&n| n == 0)\n}\n"] = "fn is_anagram(a: &str, b: &str) -> bool {\n    let mut count = [0i32; ___];    // 文字 1 つにつき 1 マス\n    for c in a.bytes() { count[(c - b'a') as usize] += 1; }\n    for c in b.bytes() { count[(c - b'a') as usize] -= 1; }\n    count.iter().all(|&n| n == 0)\n}\n",
  ["fn is_palindrome(s: &str) -> bool {\n    // forwards and backwards, compared element by element\n    s.chars().eq(s.chars().___())\n}\n"] = "fn is_palindrome(s: &str) -> bool {\n    // 前からと後ろから、要素ごとに比べる\n    s.chars().eq(s.chars().___())\n}\n",
  ["fn is_palindrome(s: &str) -> bool {\n    let t: Vec<char> = s.chars()\n        .___(|c| c.is_alphanumeric())  // letters, digits\n        .map(|c| c.to_ascii_lowercase())\n        .collect();\n    t.iter().eq(t.iter().rev())\n}\n"] = "fn is_palindrome(s: &str) -> bool {\n    let t: Vec<char> = s.chars()\n        .___(|c| c.is_alphanumeric())  // 文字と数字\n        .map(|c| c.to_ascii_lowercase())\n        .collect();\n    t.iter().eq(t.iter().rev())\n}\n",
