  ["impl Order { } holds the methods. Data and behaviour stay in two blocks. o.total() is 36."] = "impl Order { } がメソッドを持つ。データと振る舞いは 2 つのブロックに分かれる。o.total() は 36。",
  ["impl Receipt<'_> {\n    // Self in, one reference out: no lifetime name needed.\n    fn who(&self) -> ___ {\n        self.name\n    }\n}\n"] = "impl Receipt<'_> {\n    // self が入り、参照が 1 つ出る: ライフタイム名は不要。\n    fn who(&self) -> ___ {\n        self.name\n    }\n}\n",
  ["impl Trait in return position: static dispatch, no Box, closures stay unnamed."] = "戻り値位置の impl Trait: 静的ディスパッチ、Box なし、クロージャは無名のまま。",
  ['impl ___<ParseIntError> for OrderError {\n    fn from(e: ParseIntError) -> Self {\n        OrderError::BadQty(e)\n    }\n}\n// "1x8".parse::<i32>()? now becomes BadQty\n'] = 'impl ___<ParseIntError> for OrderError {\n    fn from(e: ParseIntError) -> Self {\n        OrderError::BadQty(e)\n    }\n}\n// "1x8".parse::<i32>()? はこれで BadQty になる\n',
  ["impl fmt::Display gives to_string() and {} for free. The till prints one clean line."] = "impl fmt::Display で to_string() と {} がただで手に入る。レジはきれいな1行を印字する。",
  ["impl fmt::Display gives {} and .to_string() for free. The order board reads: pineapple bun x2."] = "impl fmt::Display で {} と .to_string() がおまけで手に入る。注文ボードの表示: pineapple bun x2。",
  ["impl std::error::Error for OrderError {} - now it fits in Box<dyn Error> and ? chains."] = "impl std::error::Error for OrderError {} - これで Box<dyn Error> に収まり、? でつなげる。",
  ['import "errors"\nvar ErrCold = errors.___("coffee is cold")\n'] = 'import "errors"\nvar ErrCold = errors.___("coffee is cold")\n',
  ['import "fmt" then fmt.Println. The kiosk beeps.'] = 'import "fmt" してから fmt.Println。キオスクがピッと鳴ります。',
  ['import "maps"\n\nfor k := range maps.___(prices) {   // iterator\n    fmt.Println(k)\n}\n'] = 'import "maps"\n\nfor k := range maps.___(prices) {   // イテレータ\n    fmt.Println(k)\n}\n',
  ['import "net/http"\n\nhttp.___("/order", serve)   // path -> function\n'] = 'import "net/http"\n\nhttp.___("/order", serve)   // パス -> 関数\n',
  ['import "slices"\n\nslices.___(names)          // in place, any ordered type\n'] = 'import "slices"\n\nslices.___(names)          // その場で、順序付き型なら何でも\n',
  ['import "strconv"\nn, err := strconv.___("18")   // 18, nil\ns := strconv.Itoa(n)          // back to "18"\n'] = 'import "strconv"\nn, err := strconv.___("18")   // 18, nil\ns := strconv.Itoa(n)          // "18" に戻す\n',
  ['import "strings"\nsign := strings.___("lucky mac")   // "LUCKY MAC"\n'] = 'import "strings"\nsign := strings.___("lucky mac")   // "LUCKY MAC"\n',
  ['import "sync/___"\nvar count int64\n___.AddInt64(&count, 1)   // lock-free\n'] = 'import "sync/___"\nvar count int64\n___.AddInt64(&count, 1)   // ロックフリー\n',
  ['import "unicode/utf8"\nn := utf8.___("銅鑼灣")   // 3\n'] = 'import "unicode/utf8"\nn := utf8.___("銅鑼灣")   // 3\n',
  ["import ( ... ) groups them. The door unlocks."] = "import ( ... ) でまとめます。ドアが開きます。",
  ['import _ "embed"\n\n//go:___ menu.json\nvar menu []byte\n'] = 'import _ "embed"\n\n//go:___ menu.json\nvar menu []byte\n',
  ["init runs after package variables are set and before main. Keep it small."] = "init はpackage変数の初期化後、main の前に走ります。小さく保ちましょう。",
  ["insert walks down until it finds an empty spot. Which pattern is the empty spot?"] = "insert は空きが見つかるまで下りていく。空きを表すパターンは？",
  ['int is 0, string is "", bool is false, pointer is nil.'] = 'int は 0、string は ""、bool は false、pointer は nil です。',
  ["interface { Pay(int) error }. The till does not care if it is Octopus or cash."] = "interface { Pay(int) error }。レジはオクトパスか現金かを気にしません。",
  ["iota is Go's enum counter. Lines without a value repeat the one above."] = "iota はGoのenumカウンタです。値のない行は上の行を繰り返します。",
  ["is_some_and(|e| e < 10) beats map(..).unwrap_or(false). Review clean at 17:59. SHIPPED."] = "is_some_and(|e| e < 10) は map(..).unwrap_or(false) より良い。17:59 にレビュー完了。SHIPPED。",
  ["iter() borrows, into_iter() consumes. map, filter, collect, sum, fold: no index bugs."] = "iter() は借用、into_iter() は消費。map、filter、collect、sum、fold: インデックスのバグなし。",
  ["iter() yields &T. into_iter() yields T and eats the Vec. Dish zero prints again."] = "iter() は &T を返す。into_iter() は T を返して Vec を食べる。0番の料理がまた印字される。",
  ["iter().sum() needs the result type written down. map, filter, count and collect live on the same chain."] = "iter().sum() は結果の型を書く必要がある。map、filter、count、collect も同じチェーンに乗る。",
  ["iter.Seq[T] is func(yield func(T) bool). for x := range Items() just works."] = "iter.Seq[T] は func(yield func(T) bool)。for x := range Items() がそのまま動きます。",
  ["j moves left as i moves right. Stop when they meet."] = "i が右へ進むとき j は左へ。出会ったら止まる。",
  ["jobs := make(chan int, 10)\nresults := make(chan int, 10)\nvar wg sync.WaitGroup\nfor w := 1; w <= 3; w++ {\n    wg.___(1)\n    go worker(jobs, results, &wg)\n}\n"] = "jobs := make(chan int, 10)\nresults := make(chan int, 10)\nvar wg sync.WaitGroup\nfor w := 1; w <= 3; w++ {\n    wg.___(1)\n    go worker(jobs, results, &wg)\n}\n",
  ["join! waits for all; select! returns on the first. 200 ms total instead of 400."] = "join! は全部を待つ。select! は最初のひとつで返る。合計 400 ms ではなく 200 ms。",
  ["join() blocks until the thread ends and returns Result<T>; Err means the thread panicked. 180 seconds to steep."] = "join() はスレッドが終わるまでブロックし、Result<T> を返す。Err はスレッドが panic したということ。蒸らし時間は 180 秒。",
  ["json only sees exported fields. Name the item field: Item or item?"] = "json はエクスポートされたフィールドしか見ません。item フィールドの名前は: Item か item か？",
  ["json sees exported fields only. Tags pick the key. Marshal out, Unmarshal in."] = "json はエクスポートされたフィールドだけ。タグでキーを指定。Marshal で出し、Unmarshal で入れる。",
  ["l[i] <= r[j] keeps the merge stable. The leftovers are appended with extend. O(n) per merge."] = "l[i] <= r[j] がマージを安定に保つ。余りは extend で後ろに足す。1 回のマージは O(n)。",
  ['label := fmt.___("%s $%d", item, price)   // "set $25"\n'] = 'label := fmt.___("%s $%d", item, price)   // "set $25"\n',
  ["largest compares with >. Which trait must T promise?"] = "largest は > で比べる。T が約束すべきトレイトは？",
  ["len counts bytes. 灣 is one character. In UTF-8, how many bytes?"] = "len はバイト数を数えます。灣 は1文字。UTF-8 では何バイト？",
  ["len is how many you can see. cap is how many fit before a new array."] = "len は見えている数。cap は新しい配列なしで入る数。",
  ["len() is bytes. Slicing &s[0..4] in the middle of 鑼 panics: not a char boundary."] = "len() はバイト数。鑼 の途中で &s[0..4] とスライスすると panic: 文字境界ではない。",
  ["len() returns usize. The second let shadows n with a new binding; the old one is gone. Next tram in 7."] = "len() は usize を返す。2 つ目の let は新しい束縛で n をシャドーイングし、古い方は消える。次のトラムは 7 分後。",
  ["len(s) is bytes, not characters. That is why the sign counted nine."] = "len(s) は文字数ではなくバイト数。だから看板は9と数えたのです。",
  ['let (tx, rx) = mpsc::channel();\n// Two tills, one kitchen: each till needs its own sender.\nlet tx2 = tx.___();\nthread::spawn(move || tx.send("till 1").unwrap());\nthread::spawn(move || tx2.send("till 2").unwrap());\nfor msg in rx { println!("{msg}"); }\n'] = 'let (tx, rx) = mpsc::channel();\n// レジ 2 台、厨房 1 つ: 各レジに自分の送信者が要る。\nlet tx2 = tx.___();\nthread::spawn(move || tx.send("till 1").unwrap());\nthread::spawn(move || tx2.send("till 2").unwrap());\nfor msg in rx { println!("{msg}"); }\n',
  ['let (tx, rx) = mpsc::channel();\nlet tx2 = tx.clone();\nthread::spawn(move || tx2.send("bun").unwrap());\n___(tx);   // otherwise the loop below never ends\nfor msg in rx { println!("{msg}"); }\n'] = 'let (tx, rx) = mpsc::channel();\nlet tx2 = tx.clone();\nthread::spawn(move || tx2.send("bun").unwrap());\n___(tx);   // これがないと下のループが終わらない\nfor msg in rx { println!("{msg}"); }\n',
  ["let (tx, rx) = mpsc::channel();\ntx.send(7).unwrap();\n// The kitchen waits here until an order arrives.\nlet order: u32 = rx.___().unwrap();\n"] = "let (tx, rx) = mpsc::channel();\ntx.send(7).unwrap();\n// 厨房はここで注文が来るまで待つ。\nlet order: u32 = rx.___().unwrap();\n",
  ["let Some(x) = opt else { return }; binds x for the rest of the function. No nesting."] = "let Some(x) = opt else { return }; で関数の残り全体に x を束縛。ネストなし。",
  ["let bill = vec![18, 0, 42, 0, 25];\n// into_iter gives i32; the closure sees &i32\nlet ok: Vec<_> = bill.into_iter().___(|p| *p > 0).collect();\nassert_eq!(ok, vec![18, 42, 25]);\n"] = "let bill = vec![18, 0, 42, 0, 25];\n// into_iter は i32 を返す。クロージャには &i32 が見える\nlet ok: Vec<_> = bill.into_iter().___(|p| *p > 0).collect();\nassert_eq!(ok, vec![18, 42, 25]);\n",
  ["let binds. mut allows change. const needs a type. as converts. A new let can shadow an old name."] = "let で束縛。mut で変更を許可。const には型が必要。as で変換。新しい let は古い名前をシャドーイングできる。",
  ['let dish = "curry rice";\nlet qty = 2;\n// like println! but it returns the String\nlet line = ___!("{qty} x {dish}");\n'] = 'let dish = "curry rice";\nlet qty = 2;\n// println! に似ているが String を返す\nlet line = ___!("{qty} x {dish}");\n',
  ['let dishes = ["curry rice", "noodles", "toast"];\n// nothing runs before this call; turbofish names the type\nlet lens = dishes.iter().map(|d| d.len()).___::<Vec<_>>();\nassert_eq!(lens, vec![10, 7, 5]);\n'] = 'let dishes = ["curry rice", "noodles", "toast"];\n// この呼び出しまで何も動かない。ターボフィッシュで型を指名\nlet lens = dishes.iter().map(|d| d.len()).___::<Vec<_>>();\nassert_eq!(lens, vec![10, 7, 5]);\n',
  ['let dishes = ["curry rice", "noodles", "toast"];\n// yields (usize, &&str) pairs, starting from 0\nfor (i, d) in dishes.iter().___() {\n    println!("{}. {d}", i + 1);\n}\n'] = 'let dishes = ["curry rice", "noodles", "toast"];\n// 0 から始まる (usize, &&str) の組を返す\nfor (i, d) in dishes.iter().___() {\n    println!("{}. {d}", i + 1);\n}\n',
  ['let dishes = vec!["curry rice", "noodles", "toast"];\n// borrows every element as &&str; dishes stays usable\nfor d in dishes.___() {\n    println!("ticket: {d}");\n}\n'] = 'let dishes = vec!["curry rice", "noodles", "toast"];\n// 各要素を &&str として借用。dishes はそのまま使える\nfor d in dishes.___() {\n    println!("ticket: {d}");\n}\n',
  ['let district = "銅鑼灣";\nlet n = district.___().count();\nassert_eq!(n, 3);\n// the receipt now cuts at whole characters\n'] = 'let district = "銅鑼灣";\nlet n = district.___().count();\nassert_eq!(n, 3);\n// これでレシートは文字単位で切れる\n',
  ["let else, matches!, impl Trait, ..=, ? on Option, is_some_and: less nesting, same safety."] = "let else、matches!、impl Trait、..=、Option への ?、is_some_and: ネストは減り、安全性は同じ。",
  ['let eta: Option<u32> = fetch_eta_cached(order.id);\n// Rust 1.70: None -> false, Some(e) -> the closure result\nlet fast = eta.___(|e| e < 10);\nif fast { println!("promise the customer 10 minutes"); }\n'] = 'let eta: Option<u32> = fetch_eta_cached(order.id);\n// Rust 1.70: None -> false、Some(e) -> クロージャの結果\nlet fast = eta.___(|e| e < 10);\nif fast { println!("promise the customer 10 minutes"); }\n',
  ['let menu = vec!["bun", "egg tart", "milk tea"];\n// Borrow menu from threads; all end before the block does.\nthread::___(|s| {\n    s.spawn(|| println!("{}", menu[0]));\n    s.spawn(|| println!("{}", menu[1]));\n});\n'] = 'let menu = vec!["bun", "egg tart", "milk tea"];\n// スレッドから menu を借用。全部ブロックより先に終わる。\nthread::___(|s| {\n    s.spawn(|| println!("{}", menu[0]));\n    s.spawn(|| println!("{}", menu[1]));\n});\n',
  ["let mut count = 0; Immutable by default is Rust's first safety rule. The sign counts again."] = "let mut count = 0; デフォルトで不変、これが Rust の安全ルール第一条。看板がまた数え始める。",
  ['let mut counts: HashMap<&str, u32> = HashMap::new();\nfor w in "muffin coffee muffin".split(\' \') {\n    // start at 0 if w is new, then bump it either way\n    *counts.entry(w).___(0) += 1;\n}\nassert_eq!(counts["muffin"], 2);\n'] = 'let mut counts: HashMap<&str, u32> = HashMap::new();\nfor w in "muffin coffee muffin".split(\' \') {\n    // w が新しければ 0 から。どちらにせよ増やす\n    *counts.entry(w).___(0) += 1;\n}\nassert_eq!(counts["muffin"], 2);\n',
  ["let mut handles = Vec::new();\nfor id in 0..3 {\n    let rx = Arc::clone(&rx);\n    // a new OS thread runs the closure; move hands over rx\n    handles.push(thread::___(move || worker(id, rx)));\n}\n"] = "let mut handles = Vec::new();\nfor id in 0..3 {\n    let rx = Arc::clone(&rx);\n    // 新しい OS スレッドがクロージャを走らせる。move で rx を渡す\n    handles.push(thread::___(move || worker(id, rx)));\n}\n",
  ["let mut ids = vec![9, 2, 7, 2, 5];\n// equal ids may swap places; nobody can tell\nids.___();\nassert_eq!(ids, [2, 2, 5, 7, 9]);\n"] = "let mut ids = vec![9, 2, 7, 2, 5];\n// 等しい id は入れ替わるかもしれないが、誰にも分からない\nids.___();\nassert_eq!(ids, [2, 2, 5, 7, 9]);\n",
  ['let mut left = 3;\n___ left > 0 {\n    left -= 1;\n    if left == 1 { continue; }   // skip this round\n    println!("{}", left);\n}\n'] = 'let mut left = 3;\n___ left > 0 {\n    left -= 1;\n    if left == 1 { continue; }   // この回はスキップ\n    println!("{}", left);\n}\n',
  ['let mut order = String::new();\norder.___("curry rice");\norder.___(" + hash brown");\nlet loud = order.to_uppercase();\n'] = 'let mut order = String::new();\norder.___("curry rice");\norder.___(" + hash brown");\nlet loud = order.to_uppercase();\n',
  ['let mut tray = vec![7, 8];\n// pop returns an Option: a value, or None if empty.\nif let ___(id) = tray.pop() {\n    println!("serving order {id}");\n}\n'] = 'let mut tray = vec![7, 8];\n// pop は Option を返す: 値か、空なら None。\nif let ___(id) = tray.pop() {\n    println!("serving order {id}");\n}\n',
  ['let mut tries = 0;\nlet code = ___ {\n    tries += 1;\n    if tries == 3 { break tries * 10; }\n};\nprintln!("{}", code);   // 30\n'] = 'let mut tries = 0;\nlet code = ___ {\n    tries += 1;\n    if tries == 3 { break tries * 10; }\n};\nprintln!("{}", code);   // 30\n',
  ["let n = if a > b { a } else { b }; Both branches must have the same type. n is 22."] = "let n = if a > b { a } else { b }; 両方の分岐は同じ型でなければならない。n は 22。",
  ['let order = Order { name: "toast".into(), qty: 2 };\n// takes a reference; returns Result<String, Error>\nlet text = serde_json::___(&order)?;\nassert_eq!(text, r#"{"name":"toast","qty":2}"#);\n'] = 'let order = Order { name: "toast".into(), qty: 2 };\n// 参照を受け取り、Result<String, Error> を返す\nlet text = serde_json::___(&order)?;\nassert_eq!(text, r#"{"name":"toast","qty":2}"#);\n',
  ['let order = String::from("pineapple bun");\n// The thread may outlive this block: give it the String.\nlet h = thread::spawn(___ || {\n    println!("toasting {order}");\n});\nh.join().unwrap();\n'] = 'let order = String::from("pineapple bun");\n// スレッドはこのブロックより長生きするかも: String を渡してしまう。\nlet h = thread::spawn(___ || {\n    println!("toasting {order}");\n});\nh.join().unwrap();\n',
  ["let price = 28; The type is inferred as i32. Without mut it can never change."] = "let price = 28; 型は i32 と推論される。mut がなければ二度と変えられない。",
  ['let prices = [18, 22, 45, 60];       // already sorted\n// halve the range each step\nmatch prices.___(&45) {\n    Ok(i) => println!("found at {i}"),\n    Err(i) => println!("would insert at {i}"),\n}\n'] = 'let prices = [18, 22, 45, 60];       // もうソート済み\n// 毎回、範囲を半分にする\nmatch prices.___(&45) {\n    Ok(i) => println!("found at {i}"),\n    Err(i) => println!("would insert at {i}"),\n}\n',
  ["let prices = vec![18, 42, 25];\n// acc starts at 0; the closure returns the next acc\nlet total = prices.iter().___(0, |acc, p| acc + p);\nassert_eq!(total, 85);\n"] = "let prices = vec![18, 42, 25];\n// acc は 0 から始まる。クロージャが次の acc を返す\nlet total = prices.iter().___(0, |acc, p| acc + p);\nassert_eq!(total, 85);\n",
  ["let prices = vec![18, 42, 25];\n// the turbofish tells it which number type to add into\nlet total = prices.iter().___::<i32>();\nassert_eq!(total, 85);\n"] = "let prices = vec![18, 42, 25];\n// ターボフィッシュでどの数値型に足し込むか伝える\nlet total = prices.iter().___::<i32>();\nassert_eq!(total, 85);\n",
  ["let qty = vec![1, 2, 3];\n// a closure: the parameter sits between two pipes\nlet doubled: Vec<i32> = qty.iter().map(___ x * 2).collect();\nassert_eq!(doubled, vec![2, 4, 6]);\n"] = "let qty = vec![1, 2, 3];\n// クロージャ: 引数は2本のパイプの間に置く\nlet doubled: Vec<i32> = qty.iter().map(___ x * 2).collect();\nassert_eq!(doubled, vec![2, 4, 6]);\n",
  ["let sold = Arc::new(Mutex::new(0u32));\n// Each thread needs its own handle to the same counter.\nlet mine = ___(&sold);\nthread::spawn(move || { *mine.lock().unwrap() += 1; });\n"] = "let sold = Arc::new(Mutex::new(0u32));\n// 各スレッドに同じカウンタへの自分のハンドルが要る。\nlet mine = ___(&sold);\nthread::spawn(move || { *mine.lock().unwrap() += 1; });\n",
  ["let sold = Arc::new(Mutex::new(0u32));\n// Take the guard; it opens again when it goes out of scope.\nlet mut n = sold.___().unwrap();\n*n += 1;\n"] = "let sold = Arc::new(Mutex::new(0u32));\n// ガードを取る。スコープを抜けるとまた開く。\nlet mut n = sold.___().unwrap();\n*n += 1;\n",
  ['let text = r#"{"dish":"toast","tags":["hot","new"]}"#;\n// an enum: Null, Bool, Number, String, Array, Object\nlet v: serde_json::___ = serde_json::from_str(text)?;\nprintln!("{}", v["tags"][0]);   // "hot"\n'] = 'let text = r#"{"dish":"toast","tags":["hot","new"]}"#;\n// enum: Null、Bool、Number、String、Array、Object\nlet v: serde_json::___ = serde_json::from_str(text)?;\nprintln!("{}", v["tags"][0]);   // "hot"\n',
  ['let text = r#"{"name":"noodles","qty":1}"#;\n// the type annotation tells serde what to build\nlet order: Order = serde_json::___(text)?;\nassert_eq!(order.qty, 1);\n'] = 'let text = r#"{"name":"noodles","qty":1}"#;\n// 型注釈が serde に何を組み立てるか伝える\nlet order: Order = serde_json::___(text)?;\nassert_eq!(order.qty, 1);\n',
  ['let typed = "18";\n// FromStr does the work; the turbofish picks the type\nlet qty = typed.___::<i32>()?;\nprintln!("{qty} sets");\n'] = 'let typed = "18";\n// FromStr が仕事をする。ターボフィッシュで型を選ぶ\nlet qty = typed.___::<i32>()?;\nprintln!("{qty} sets");\n',
  ['light := "green"\n___ light {\ncase "green":\n    walk()\n}\n'] = 'light := "green"\n___ light {\ncase "green":\n    walk()\n}\n',
  ["lo, hi := 0, len(a)         // [lo, hi)\nfor lo < hi {\n    mid := lo + (hi-lo)/___\n"] = "lo, hi := 0, len(a)         // [lo, hi)\nfor lo < hi {\n    mid := lo + (hi-lo)/___\n",
  ["lock() returns a MutexGuard; unwrap fails only if another thread panicked while holding it. The guard unlocks on drop."] = "lock() は MutexGuard を返す。unwrap が失敗するのは、別スレッドが握ったまま panic したときだけ。ガードは drop でロックを外す。",
  ["log n levels, n work per level: O(n log n). The base case is a slice of 0 or 1."] = "段数は log n、1 段あたりの仕事は n: O(n log n)。基底ケースは長さ 0 か 1 のスライス。",
  ['log.Fatal(http.___(":8080", nil))   // nil = default mux\n'] = 'log.Fatal(http.___(":8080", nil))   // nil = デフォルトの mux\n',
  ["longest returns one of its inputs. Which lifetime does the return value carry?"] = "longest は入力のどちらかを返す。戻り値が持つライフタイムは？",
  ["loop { ... break value; } is an expression. code becomes 30. The gate stops spinning."] = "loop { ... break value; } は式。code は 30 になる。ゲートの空回りが止まる。",
  ["low:high. Includes low, excludes high. Same backing array, no copy."] = "low:high。low を含み high を含まない。同じ内部配列、コピーなし。",
  ["main can fail in many ways. Which pointer type wraps any dyn Error?"] = "main はいろんな形で失敗しうる。どんな dyn Error も包むポインタ型は？",
  ["main sends on an unbuffered channel with nobody receiving. The runtime reports: all goroutines are asleep - ___!"] = "main が受信者のいないバッファなし channel に送信。ランタイムの報告：all goroutines are asleep - ___!",
  ["make (or a {} literal) before the first write. Reading a nil map is safe."] = "最初の書き込みの前に make(か {} リテラル)。nil map の読み取りは安全です。",
  ["make(T, len, cap) for slices, maps, channels. new(T) only gives a zeroed pointer."] = "make(T, len, cap) は slice、map、channel 用。new(T) はゼロ値への pointer を返すだけ。",
  ["make(chan string). Unbuffered: send waits for receive."] = "make(chan string)。バッファなし：送信は受信を待ちます。",
  ["map, then [key type], then value type."] = "map、次に [キーの型]、次に値の型。",
  ["map[K]bool is the everyday set. Missing keys read as false."] = "map[K]bool が日常の set。ないキーは false と読めます。",
  ["map[string]int. make(map[string]int) if you start empty."] = "map[string]int。空から始めるなら make(map[string]int)。",
  ["maps.Keys and maps.Values return iter.Seq, so range works on them directly."] = "maps.Keys と maps.Values は iter.Seq を返すので、そのまま range できます。",
  ["match code { 1 => ..., _ => ... } Each arm is pattern => value. The compiler checks every case is covered."] = "match code { 1 => ..., _ => ... } 各アームは パターン => 値。すべてのケースが網羅されているかコンパイラが確認する。",
  ["matches!(v, Pat) expands to match v { Pat => true, _ => false }. Guards allowed: Some(n) if n > 3."] = "matches!(v, Pat) は match v { Pat => true, _ => false } に展開される。ガードも可: Some(n) if n > 3。",
  ["memo.get(&n) is O(1). Hit: return it. Miss: compute it. That is memoization."] = "memo.get(&n) は O(1)。ヒットなら返す。ミスなら計算する。それがメモ化。",
  ["min, max and clear joined len, cap, append in Go 1.21."] = "Go 1.21 で min、max、clear が len、cap、append の仲間入り。",
  ["module, go, require. go.sum next to it holds the checksums."] = "module、go、require。隣の go.sum がチェックサムを保持します。",
  ["move || captures by value. Without it the closure would borrow order, and a borrow cannot be proven to outlive the thread."] = "move || は値でキャプチャする。なければクロージャは order を借用するが、借用がスレッドより長く生きるとは証明できない。",
  ["mpsc: multi-producer, single-consumer. Job is Send so it may cross to another thread; FnOnce because each ticket runs once."] = "mpsc: multi-producer, single-consumer。Job は Send なので別のスレッドへ渡れる。伝票は一度しか走らないので FnOnce。",
  ["mpsc::channel gives a Sender and a Receiver. Clone the Sender for many producers; the loop ends when all are dropped."] = "mpsc::channel は Sender と Receiver をくれる。生産者を増やすなら Sender を clone。全部 drop されるとループが終わる。",
  ["mpsc::channel() returns (Sender<T>, Receiver<T>). mpsc: multi-producer, single-consumer. The pipe is unbounded."] = "mpsc::channel() は (Sender<T>, Receiver<T>) を返す。mpsc: multi-producer, single-consumer。パイプは無制限。",
  ["mu.Lock()\ndefer mu.___()          // even on panic\ncount++\n"] = "mu.Lock()\ndefer mu.___()          // panic 時も\ncount++\n",
  ["n := 7\nhalf := ___(n) / 2      // 3.5, not 3\n"] = "n := 7\nhalf := ___(n) / 2      // 3 ではなく 3.5\n",
  ["n is an int. Divide it as a floating point number. Fill: half := ___(n) / 2"] = "n は int。浮動小数点数として割ってください。埋める: half := ___(n) / 2",
  ['n, ___ := prices["hashbrown"]\nif !___ {\n    // missing\n}\n'] = 'n, ___ := prices["hashbrown"]\nif !___ {\n    // 見つからない\n}\n',
  ["net/http: handlers and a server"] = "net/http: handler とサーバ",
  ["nil check first, then recurse. insert returns the (possibly new) subtree root."] = "まず nil チェック、それから再帰。insert は（新しいかもしれない）部分木の根を返します。",
  ['o := Order{Item: "set", Price: 25}\nfmt.Printf("___\\n", o)    // {Item:set Price:25}\n'] = 'o := Order{Item: "set", Price: 25}\nfmt.Printf("___\\n", o)    // {Item:set Price:25}\n',
  ["ok, an underscore, then the word you use to offer an alternative."] = "ok、アンダースコア、そして代案を示すときに使う単語。",
  ["ok_or(err) maps Some(v) to Ok(v) and None to Err(err). Now ? works on it too."] = "ok_or(err) は Some(v) を Ok(v) に、None を Err(err) に写す。これで ? も使える。",
  ['omit + empty, one word, after the comma. json:"-" hides a field entirely.'] = 'omit + empty、カンマの後ろに1語。json:"-" はフィールドを完全に隠します。',
  ['omitempty drops zero values. "-" drops the field always.'] = 'omitempty はゼロ値を落とします。"-" は常にフィールドを落とします。',
  ["or, underscore, insert. Takes the starting value and returns &mut u32, which the * dereferences."] = "or、アンダースコア、insert。開始値を取り &mut u32 を返し、それを * がデリファレンスする。",
  ["or_ plus the word for Default::default(). An empty Vec is the default Vec."] = "or_ に Default::default() を表す語を足したもの。空の Vec がデフォルトの Vec。",
  ["orders.push(18). pop() takes the last one back. The Vec reallocates when it runs out of room."] = "orders.push(18)。pop() は最後の 1 つを取り戻す。Vec は場所が足りなくなると再確保する。",
  ['p := ___Order{Item: "set"}   // p is *Order\np.Price = 25                  // Go dereferences for you\n'] = 'p := ___Order{Item: "set"}   // p は *Order\np.Price = 25                  // Goが自動で参照外し\n',
  ['package main\n___ (\n    "fmt"\n    "os"\n)\n'] = 'package main\n___ (\n    "fmt"\n    "os"\n)\n',
  ["package main\n___ opens = 6          // Lucky Mac hour, never changes\n"] = "package main\n___ opens = 6          // Lucky Macの開店時刻、変わらない\n",
  ['package main\n___ shop string = "Lucky Mac"   // package level: no :=\nfunc main() {\n    fmt.Println(shop)\n}\n'] = 'package main\n___ shop string = "Lucky Mac"   // packageレベル: := は不可\nfunc main() {\n    fmt.Println(shop)\n}\n',
  ["package main\nfunc main() {\n    floor ___ 8      // type inferred as int\n}\n"] = "package main\nfunc main() {\n    floor ___ 8      // 型は int と推論される\n}\n",
  ['package main\nimport "___"\nfunc main() {\n    Println("hash brown")\n}\n'] = 'package main\nimport "___"\nfunc main() {\n    Println("hash brown")\n}\n',
  ['package main\nimport "fmt"\nfunc main() {\n    fmt.___("morning set")   // capital P: exported\n}\n'] = 'package main\nimport "fmt"\nfunc main() {\n    fmt.___("morning set")   // 大文字のP: エクスポート\n}\n',
  ['package main\nvar menu map[string]int\nfunc ___() {                // before main\n    menu = map[string]int{"muffin": 18}\n}\nfunc main() {}\n'] = 'package main\nvar menu map[string]int\nfunc ___() {                // main の前\n    menu = map[string]int{"muffin": 18}\n}\nfunc main() {}\n',
  ["package main is the entry. Other folders are libraries."] = "package main が入口です。他のフォルダはライブラリです。",
  ["panic stops the goroutine. recover() inside defer can save it. Rare in libraries."] = "panic は goroutine を止めます。defer 内の recover() で救えます。ライブラリでは稀です。",
  ["panic unwinds the stack running every defer. recover in a defer can stop it."] = "panic はスタックを巻き戻し、全 defer を実行します。defer 内の recover で止められます。",
  ["parse::<i32>() names the generic explicitly. Same trick: collect::<Vec<_>>(). 12 x 18 = 216."] = "parse::<i32>() はジェネリックを明示的に指名する。同じ技: collect::<Vec<_>>()。12 x 18 = 216。",
  ["plate only receives. Fill the parameter type: in ___ string"] = "plate は受信のみ。引数の型を埋めて：in ___ string",
  ["pop returns an Option. Which arm holds a value?"] = "pop は Option を返す。値を持つアームは？",
  ["pop the first node. We only have &mut head, so move the node out and leave None behind. Which Option method?"] = "先頭のノードを pop する。手元にあるのは &mut head だけなので、ノードを取り出して None を置いていく。Option のどのメソッド？",
  ["pop, underscore, the end that is not back. The while let ends when it returns None."] = "pop、アンダースコア、back でない方の端。None を返すと while let が終わる。",
  ["pop_front is BFS, pop is DFS: the only difference is which end. Both O(V + E). Combo x3."] = "pop_front なら BFS、pop なら DFS: 違いはどちらの端かだけ。どちらも O(V + E)。コンボ x3。",
  ["pop_front is O(1). Stations come out in rings: one hop, two hops, three. That is BFS."] = "pop_front は O(1)。駅は輪になって出てくる: 1 ホップ、2 ホップ、3 ホップ。それが BFS。",
  ['prices := ___{\n    "muffin": 18,\n}\n'] = 'prices := ___{\n    "muffin": 18,\n}\n',
  ["prices.len() is 3. is_empty() is the idiomatic way to ask for zero. The board counts to twelve."] = "prices.len() は 3。ゼロかどうかは is_empty() で聞くのが慣用的。ボードが 12 まで数える。",
  ["println is a macro, not a function. Which character ends its name?"] = "println は関数ではなくマクロ。名前の最後はどの文字？",
  ["push adds one char. This one adds a whole str. Two words, underscore."] = "push は char をひとつ足す。これは str をまるごと足す。2単語、アンダースコア。",
  ["push_str borrows the &str and copies it in. to_uppercase() makes a new String."] = "push_str は &str を借用して中にコピーする。to_uppercase() は新しい String を作る。",
  ["queue[0] then queue[1:] is the Go queue. For big queues use a ring or container/list."] = "queue[0] の後に queue[1:] が Go のキュー。大きなキューにはリングか container/list を。",
  ["r must be allowed to change a. Which two-part borrow gives write access?"] = "r は a を変更できなければならない。書き込みアクセスを与える 2 部構成の借用は？",
  ["range 3 counts 0..2. Since 1.22 each iteration also gets its own i."] = "range 3 は 0..2 を数えます。1.22 からは各反復が独自の i を持ちます。",
  ["range decodes UTF-8 for you: byte index plus rune. string(r) turns it back."] = "range が UTF-8 をデコードしてくれます: バイト位置と rune。string(r) で戻せます。",
  ["range over a channel ends when the sender calls close. Without close it blocks forever."] = "channel の range は送信側が close を呼ぶと終わります。close がなければ永遠にブロックします。",
  ["range over a channel. Note the directional channel types in the signature."] = "channel を range する。シグネチャの方向付き channel 型に注目。",
  ["range over a string gives runes. Print each one as text: fill ___(r)"] = "string を range すると rune が得られます。それぞれを文字として表示: ___(r) を埋めてください",
  ["range over an int, min and max, slices and maps packages, iter.Seq for range."] = "int を range、min と max、slices と maps パッケージ、range 用の iter.Seq。",
  ["recv blocks with no busy loop. Not while let: its temporaries live for the whole body and would hold the lock during job()."] = "recv はビジーループなしでブロックする。while let ではダメ: 一時値が本体の間ずっと生きて、job() の実行中も鍵を握ってしまう。",
  ["reqwest::get(url).await?.text().await? - two awaits, two places it can fail. Riders roll out."] = "reqwest::get(url).await?.text().await? - await が2回、失敗しうる場所も2つ。ライダーたちが出発する。",
  ["return 0; exits at once. The tail expression n * 18 - 5 handles every other case."] = "return 0; はすぐに抜ける。末尾の式 n * 18 - 5 が残りのケースをすべて処理する。",
  ["return sends every result at once. The bool and the error travel together."] = "return はすべての結果を一度に返します。bool と error は一緒に運ばれます。",
  ["rune is one code point. 'x' literals are runes, \"x\" literals are strings."] = "rune はコードポイントひとつ。'x' リテラルは rune、\"x\" リテラルは string です。",
  ["rx.recv() blocks until a value arrives; Err when every Sender is gone. Order 7 hits the pass."] = "rx.recv() は値が届くまでブロックする。Sender が全部消えると Err。7 番の注文がパスに届く。",
  ['s := "灣"\nfmt.Println(len(s))     // prints ___\n'] = 's := "灣"\nfmt.Println(len(s))     // ___ と表示\n',
  ["s := ___{1, 2, 3}     // slice, length 3\n"] = "s := ___{1, 2, 3}     // slice、長さ 3\n",
  ["s[1:3] is a slice of a slice. Changing two[0] changes tray[1] too."] = "s[1:3] は slice の slice。two[0] を変えると tray[1] も変わります。",
  ["seats as f64. i32 / f64 does not compile in Rust; as makes the intent explicit."] = "seats as f64。Rust では i32 / f64 はコンパイルできない。as で意図を明示する。",
  ["seats is an i32 but the division needs a float. Which keyword converts it?"] = "seats は i32 だが、割り算には浮動小数点が要る。変換するキーワードは？",
  ["seen := map[int]int{}          // value -> index\nfor i, x := range nums {\n    if j, ok := seen[target-___]; ok {\n        return []int{j, i}\n    }\n    seen[x] = i\n}\n"] = "seen := map[int]int{}          // 値 -> インデックス\nfor i, x := range nums {\n    if j, ok := seen[target-___]; ok {\n        return []int{j, i}\n    }\n    seen[x] = i\n}\n",
  ["seen.insert(m) is one lookup for check and mark. Without it, a loop in the map queues forever."] = "seen.insert(m) は確認と印つけを 1 回の検索で済ませる。これがないと、路線図の閉路で永遠にキューが伸びる。",
  ["select"] = "select",
  ["select waits on several channel ops. default is the non-blocking branch."] = "select は複数の channel 操作を待ちます。default がノンブロッキングの分岐です。",
  ["select {\ncase m := <-muffin:\n    serve(m)\n___:\n    skip()\n}\n"] = "select {\ncase m := <-muffin:\n    serve(m)\n___:\n    skip()\n}\n",
  ["select {\ncase m := <-muffin:\n    serve(m)\ncase <-ctx.___():\n    return ctx.Err()\n}\n"] = "select {\ncase m := <-muffin:\n    serve(m)\ncase <-ctx.___():\n    return ctx.Err()\n}\n",
  ['select {\ncase m := <-muffin:\n    serve(m)\ncase <-time.___(time.Second):\n    fmt.Println("timeout")\n}\n'] = 'select {\ncase m := <-muffin:\n    serve(m)\ncase <-time.___(time.Second):\n    fmt.Println("timeout")\n}\n',
  ["select { case x := <-ch: ... }. Random choice if several are ready."] = "select { case x := <-ch: ... }。複数が準備済みならランダムに選びます。",
  ["sem := make(chan struct{}, ___)\nfor _, u := range urls {\n    sem <- struct{}{}        // acquire (blocks when full)\n    go func(u string) {\n        defer func() { <-sem }()   // release\n        fetch(u) }(u)\n}\n"] = "sem := make(chan struct{}, ___)\nfor _, u := range urls {\n    sem <- struct{}{}        // 取得（満杯ならブロック）\n    go func(u string) {\n        defer func() { <-sem }()   // 解放\n        fetch(u) }(u)\n}\n",
  ["serde and JSON"] = "serde と JSON",
  ["serde_json::Value indexes with [] and returns Null when missing. Ticket four closed."] = "serde_json::Value は [] で添字アクセスでき、なければ Null を返す。チケット4完了。",
  ["serde_json::from_str::<Order>(text). from_slice for bytes, from_reader for files."] = "serde_json::from_str::<Order>(text)。バイト列には from_slice、ファイルには from_reader。",
  ["serde_json::to_string(&order) -> compact JSON. to_vec gives bytes, to_writer streams."] = "serde_json::to_string(&order) -> コンパクトな JSON。to_vec はバイト列、to_writer はストリームに書く。",
  ['shops := []string{"Lucky Mac", "Sogo"}\nfor _, name := ___ shops {\n    fmt.Println(name)\n}\n'] = 'shops := []string{"Lucky Mac", "Sogo"}\nfor _, name := ___ shops {\n    fmt.Println(name)\n}\n',
  ['skip_serializing_if = "Option::is_none" drops empty fields. default fills them on the way in.'] = 'skip_serializing_if = "Option::is_none" で空のフィールドを省く。default は読み込み時に埋める。',
  ["slices.Contains, Index, Reverse, Max: the loops you used to write by hand."] = "slices.Contains、Index、Reverse、Max: 昔は手で書いていたループたち。",
  ["slices.Sort is generic: no sort.Strings / sort.Ints per type any more."] = "slices.Sort はジェネリック: 型ごとの sort.Strings / sort.Ints はもう不要。",
  ["slow, fast := head, head\nfor fast != nil && fast.Next != nil {\n    slow = slow.Next\n    fast = fast.Next.___\n    if slow == fast { return true }   // cycle\n}\n"] = "slow, fast := head, head\nfor fast != nil && fast.Next != nil {\n    slow = slow.Next\n    fast = fast.Next.___\n    if slow == fast { return true }   // 循環\n}\n",
  ["sort, by, key with underscores. The closure returns something Ord; here a u32."] = "sort、by、key をアンダースコアでつなぐ。クロージャは Ord なものを返す。ここでは u32。",
  ["sort, underscore, the opposite of stable. A pattern-defeating quicksort inside."] = "sort、アンダースコア、stable の反対語。中身は pattern-defeating quicksort。",
  ["sort.Slice with a less function. slices.SortFunc is the generic Go 1.21 way."] = "less 関数付きの sort.Slice。slices.SortFunc は Go 1.21 のジェネリック版。",
  ["sort.___(orders, func(i, j int) bool {\n    return orders[i].Price < orders[j].Price\n})\n"] = "sort.___(orders, func(i, j int) bool {\n    return orders[i].Price < orders[j].Price\n})\n",
  ["sort_by_key is a stable merge sort, like the one you just wrote. sort_by takes a full comparator instead."] = "sort_by_key は安定なマージソート、いま書いたのと同じもの。sort_by の方は完全な比較関数を取る。",
  ["sort_unstable: O(n log n), in place, usually faster than sort. Use sort only when order among equals matters. Combo x5."] = "sort_unstable: O(n log n)、その場で、たいてい sort より速い。等しいもの同士の順序が大事なときだけ sort を使う。コンボ x5。",
  ["spawn returns a handle you can wait on. What is its type?"] = "spawn は待てるハンドルを返す。その型は？",
  ["split, underscore, at. Panics if mid is past the end; here it never is."] = "split、アンダースコア、at。mid が末尾を越えると panic するが、ここでは決して越えない。",
  ["split_at gives (&v[..mid], &v[mid..]) as one tuple. Two shared borrows of one slice are fine."] = "split_at は (&v[..mid], &v[mid..]) を 1 つのタプルで返す。1 つのスライスへの共有借用は 2 つあっても平気。",
  ["strconv.Atoi / Itoa for ints, ParseFloat and FormatFloat for floats."] = "int には strconv.Atoi / Itoa、float には ParseFloat と FormatFloat。",
  ["string is bytes, rune is a code point. utf8 counts characters, strconv converts."] = "string はバイト列、rune はコードポイント。utf8 は文字を数え、strconv は変換します。",
  ["strings has Split, Join, Contains, TrimSpace, ToUpper... all return new strings."] = "strings には Split、Join、Contains、TrimSpace、ToUpper など。すべて新しい string を返します。",
  ['struct Grill;\n// Grill promises every method of Cook.\nimpl Cook ___ Grill {\n    fn name(&self) -> String {\n        "grill".to_string()\n    }\n}\n'] = 'struct Grill;\n// Grill は Cook のすべてのメソッドを約束する。\nimpl Cook ___ Grill {\n    fn name(&self) -> String {\n        "grill".to_string()\n    }\n}\n',
  ["struct ListNode {\n    val: i32,\n    next: ___<Box<ListNode>>,   // the rest, or the end\n}\n"] = "struct ListNode {\n    val: i32,\n    next: ___<Box<ListNode>>,   // 残り、または終わり\n}\n",
  ["struct Order { id: u32, price: u32 }\nlet mut orders = vec![\n    Order { id: 7, price: 45 },\n    Order { id: 3, price: 18 },\n];\n// cheapest first; equal prices keep their order (stable)\norders.___(|o| o.price);\n"] = "struct Order { id: u32, price: u32 }\nlet mut orders = vec![\n    Order { id: 7, price: 45 },\n    Order { id: 3, price: 18 },\n];\n// 安い順。同じ値段は順序を保つ (安定)\norders.___(|o| o.price);\n",
  ["struct Order { item: String, qty: u32 } Fields are private to the module unless marked pub."] = "struct Order { item: String, qty: u32 } フィールドは pub を付けない限りモジュール内だけの非公開。",
  ["struct Order { qty: u32 }\n\n___ Order {\n    fn total(&self) -> u32 {\n        self.qty * 18\n    }\n}\n"] = "struct Order { qty: u32 }\n\n___ Order {\n    fn total(&self) -> u32 {\n        self.qty * 18\n    }\n}\n",
  ["struct Receipt<'a> { name: &'a str }: a Receipt cannot outlive the name it borrows. The compiler now checks it for you."] = "struct Receipt<'a> { name: &'a str }: Receipt は借りている名前より長生きできない。これでコンパイラが検査してくれる。",
  ['struct Wok;\nimpl Cook for Wok {\n    fn name(&self) -> String { "wok".to_string() }\n}\n// Any Cook, decided at run time, behind a reference.\nfn call(c: &___ Cook) { println!("{}", c.greet()); }\ncall(&Grill); call(&Wok);\n'] = 'struct Wok;\nimpl Cook for Wok {\n    fn name(&self) -> String { "wok".to_string() }\n}\n// 実行時に決まる任意の Cook、参照の向こうに。\nfn call(c: &___ Cook) { println!("{}", c.greet()); }\ncall(&Grill); call(&Wok);\n',
  ["struct groups fields. *T is a pointer. Methods have a receiver. interface is a set of methods."] = "struct はフィールドをまとめる。*T は pointer。メソッドにはレシーバがある。interface はメソッドの集まり。",
  ["struct groups fields. impl adds methods that take &self or &mut self. enum lists variants; match handles them all."] = "struct はフィールドをまとめる。impl は &self か &mut self を取るメソッドを足す。enum はバリアントを並べ、match がすべて処理する。",
  ["struct, impl and enum"] = "struct、impl、enum",
  ["sum takes any number of fares. Fill the parameter type: fares ___"] = "sum は任意の数の運賃を受け取る。引数の型を埋める: fares ___",
  ["sum::<i32>() adds &i32 into an i32. Without the turbofish Rust cannot pick the type."] = "sum::<i32>() は &i32 を i32 に足し込む。ターボフィッシュなしでは Rust は型を決められない。",
  ['switch light { case "green": walk() }. No break: cases do not fall through.'] = 'switch light { case "green": walk() }。break 不要。case はフォールスルーしません。',
  ["switch v.(type) gives x the concrete type in every case."] = "switch v.(type) では各 case で x が具体的な型になります。",
  ['switch x := v.(___) {\ncase int:\n    fmt.Println(x + 1)      // x is an int here\ncase string:\n    fmt.Println(x + "!")    // and a string here\n}\n'] = 'switch x := v.(___) {\ncase int:\n    fmt.Println(x + 1)      // ここでは x は int\ncase string:\n    fmt.Println(x + "!")    // ここでは string\n}\n',
  ["sync, underscore, then the word for the pipe itself."] = "sync、アンダースコア、そしてパイプそのものを表す単語。",
  ["sync.Mutex. Lock, change, Unlock. Prefer channels when you can."] = "sync.Mutex。Lock、変更、Unlock。できれば channel を優先しましょう。",
  ["sync.Once.Do runs the function once and blocks the others until it finishes. Go 1.21 adds sync.OnceValue."] = "sync.Once.Do は関数を一度だけ実行し、終わるまで他をブロックします。Go 1.21 で sync.OnceValue が追加。",
  ["sync/atomic is for single words: counters, flags. Anything bigger wants a Mutex."] = "sync/atomic は単一ワード向け：カウンタ、フラグ。それより大きいものは Mutex です。",
  ["sync_channel(n) is bounded: send blocks when n values wait. Backpressure, like a buffered Go channel. The queue moves."] = "sync_channel(n) は上限付き: n 個の値が待っていると send はブロックする。バックプレッシャー、Go の buffered channel のように。キューが動き出す。",
  ["t.Errorf marks failure and continues; t.Fatalf stops. Table tests loop over cases with t.Run."] = "t.Errorf は失敗を記録して続行、t.Fatalf は停止。テーブルテストは t.Run でケースをループします。",
  ["thiserror derives Display + Error; #[from] even writes the From impl. Ticket two closed."] = "thiserror が Display + Error を derive する。#[from] なら From の impl まで書いてくれる。チケット2完了。",
  ["thread::scope(|s| ...) joins every s.spawn before returning, so the closures may borrow without move. Three cooks, one menu."] = "thread::scope(|s| ...) は戻る前にすべての s.spawn を join するので、クロージャは move なしで借用できる。料理人 3 人、メニュー 1 つ。",
  ["thread::sleep(Duration) takes a Duration, never a bare number. Duration::from_secs and from_millis build one."] = "thread::sleep(Duration) は Duration を受け取り、生の数は受け取らない。Duration::from_secs や from_millis で作る。",
  ["thread::spawn returns JoinHandle<T>. Keep them in a Vec, or the threads are detached and main may exit first."] = "thread::spawn は JoinHandle<T> を返す。Vec に持っておかないとスレッドは切り離され、main が先に終わるかもしれない。",
  ["thread::spawn starts a thread; move gives it its data; join waits. thread::scope may borrow."] = "thread::spawn がスレッドを起こし、move がデータを渡し、join が待つ。thread::scope なら借用もできる。",
  ["thread::spawn(closure) returns a JoinHandle and runs at once on an OS thread. Rust has no green threads built in."] = "thread::spawn(closure) は JoinHandle を返し、すぐに OS スレッドで走る。Rust にはグリーンスレッドは組み込まれていない。",
  ["time.After in a select is the classic timeout. In a loop prefer a time.Timer."] = "select 内の time.After が定番のタイムアウト。ループ内では time.Timer が良いです。",
  ["tokio::spawn needs a 'static + Send future. handle.await gives Result<T, JoinError>."] = "tokio::spawn には 'static + Send な Future が必要。handle.await は Result<T, JoinError> を返す。",
  ["total only reads the order. Which receiver borrows it without change?"] = "total は注文を読むだけ。変更せずに借用するレシーバは？",
  ["trait Cook lists methods. One with a body is a default; implementors may keep it or override it."] = "trait Cook はメソッドを並べる。本体付きのものはデフォルトで、実装側はそのまま使っても上書きしてもいい。",
  ['tray := []string{"muffin", "hash", "coffee", "tea"}\ntwo := tray[___]         // {"hash", "coffee"}\n'] = 'tray := []string{"muffin", "hash", "coffee", "tea"}\ntwo := tray[___]         // {"hash", "coffee"}\n',
  ['tray := []string{"muffin", "hashbrown"}\nn := ___(tray)         // 2\n'] = 'tray := []string{"muffin", "hashbrown"}\nn := ___(tray)         // 2\n',
  ['tray := []string{"muffin"}\ntray = ___(tray, "hashbrown")\n'] = 'tray := []string{"muffin"}\ntray = ___(tray, "hashbrown")\n',
  ['tray := ___([]string, 0, 8)   // len 0, cap 8\ntray = append(tray, "muffin")\n'] = 'tray := ___([]string, 0, 8)   // len 0, cap 8\ntray = append(tray, "muffin")\n',
  ["tray := make([]string, 2, 8)\nfmt.Println(len(tray), ___(tray))   // 2 8\n"] = "tray := make([]string, 2, 8)\nfmt.Println(len(tray), ___(tray))   // 2 8\n",
  ["tray = append(tray, x). Never ignore the return."] = "tray = append(tray, x)。戻り値を無視してはいけません。",
  ["tree.as_ref() turns &Option<T> into Option<&T>. Without it, map would try to move out of the borrow."] = "tree.as_ref() は &Option<T> を Option<&T> にする。これがないと map は借用から値をムーブしようとする。",
  ["try, underscore, then the blocking method's name."] = "try、アンダースコア、そしてブロックするメソッドの名前。",
  ["try_recv() returns at once: Ok(v), Err(Empty) or Err(Disconnected). Good for polling loops; recv_timeout is the middle road."] = "try_recv() はすぐ返る: Ok(v)、Err(Empty)、Err(Disconnected) のどれか。ポーリングループ向き。recv_timeout は中間の道。",
  ["two-sum with a HashMap, palindrome with chars().rev(), anagram with a [0; 26] counter, word count with entry().or_insert(0)."] = "two-sum は HashMap、回文は chars().rev()、アナグラムは [0; 26] のカウンタ、単語数は entry().or_insert(0)。",
  ["type Floor int             // new type, underlying int\n\nf := ___(3)                // int -> Floor\n"] = "type Floor int             // 新しい型、基底は int\n\nf := ___(3)                // int -> Floor\n",
  ["type Floor int is a new type: its own methods, no accidental mixing with int."] = "type Floor int は新しい型: 独自のメソッドを持ち、int とうっかり混ざりません。",
  ["type Kitchen struct {\n    ___                  // promoted methods\n}\n"] = "type Kitchen struct {\n    ___                  // 昇格したメソッド\n}\n",
  ["type Kitchen struct { Grill }. k.Toast() calls Grill.Toast."] = "type Kitchen struct { Grill }。k.Toast() は Grill.Toast を呼びます。",
  ["type Link = Option<Box<ListNode>>;\nfn pop(head: &mut Link) -> Option<i32> {\n    // move the first node out, leave None in its place\n    let node = head.___()?;\n    *head = node.next;\n    Some(node.val)\n}\n"] = "type Link = Option<Box<ListNode>>;\nfn pop(head: &mut Link) -> Option<i32> {\n    // 先頭ノードを取り出し、代わりに None を置く\n    let node = head.___()?;\n    *head = node.next;\n    Some(node.val)\n}\n",
  ["type ListNode struct {\n    Val  int\n    Next ___             // nil at the tail\n}\n"] = "type ListNode struct {\n    Val  int\n    Next ___             // 末尾では nil\n}\n",
  ["type Name ___, then curly braces with fields."] = "type 名前 ___、そのあと波括弧にフィールド。",
  ["type Node struct {\n    Val         int\n    Left, Right ___      // nil at the leaves\n}\n"] = "type Node struct {\n    Val         int\n    Left, Right ___      // 葉では nil\n}\n",
  ["type Number interface {\n    ___int | ___float64      // underlying types\n}\nfunc Sum[T Number](xs []T) T\n"] = "type Number interface {\n    ___int | ___float64      // 基底型\n}\nfunc Sum[T Number](xs []T) T\n",
  ["type Order ___ {\n    Item  string\n    Price int\n}\n"] = "type Order ___ {\n    Item  string\n    Price int\n}\n",
  ['type Order struct {\n    Item string `json:"___"`\n}\n'] = 'type Order struct {\n    Item string `json:"___"`\n}\n',
  ['type Order struct {\n    Item string `json:"dish"`\n    Note string `json:"note,___"`   // skip when empty\n}\n'] = 'type Order struct {\n    Item string `json:"dish"`\n    Note string `json:"note,___"`   // 空なら省略\n}\n',
  ["type Order struct {\n    ___  string           // json needs a capital\n    Price int\n}\n"] = "type Order struct {\n    ___  string           // json には大文字が必要\n    Price int\n}\n",
  ["type Order struct { Item string; Price int }. A value type."] = "type Order struct { Item string; Price int }。値型です。",
  ["type Payer ___ {\n    Pay(int) error\n}\n"] = "type Payer ___ {\n    Pay(int) error\n}\n",
  ['type RefundError struct{ Amount int }\n\nfunc (e *RefundError) ___() string {\n    return "refund " + strconv.Itoa(e.Amount)\n}\n'] = 'type RefundError struct{ Amount int }\n\nfunc (e *RefundError) ___() string {\n    return "refund " + strconv.Itoa(e.Amount)\n}\n',
  ["type names a type. v.(T) asserts, switch v.(type) branches. Sprintf formats."] = "type は型に名前を付け、v.(T) はアサート、switch v.(type) は分岐。Sprintf は整形します。",
  ["type the answer"] = "答えを入力",
  ["u for unsigned, then the word for pointer size. Same type as len() returns."] = "符号なしの u に、ポインタの大きさを表す語を続ける。len() が返すのと同じ型。",
  ["u for unsigned, then the word size. It is also the type used to index a Vec."] = "u は unsigned (符号なし)、続けて size。Vec の添字に使う型でもある。",
  ["unwrap, then an underscore, then a two-letter word."] = "unwrap、アンダースコア、そして 2 文字の単語。",
  ["unwrap_or(default) returns the Ok value or your default. Sibling: unwrap_or_else(|e| ...). Zero coins, but no crash."] = "unwrap_or(default) は Ok の値か、指定した既定値を返す。兄弟に unwrap_or_else(|e| ...)。コインはゼロ、でもクラッシュはしない。",
  ['use serde::{Deserialize, ___};\n// Cargo.toml: serde = {version="1", features=["derive"]}\n#[derive(Debug, ___, Deserialize)]\nstruct Order {\n    name: String,\n    qty: u32,\n}\n'] = 'use serde::{Deserialize, ___};\n// Cargo.toml: serde = {version="1", features=["derive"]}\n#[derive(Debug, ___, Deserialize)]\nstruct Order {\n    name: String,\n    qty: u32,\n}\n',
  ["use std::collections::HashMap;\n// station id -> the ids one hop away (an adjacency list)\ntype Graph = HashMap<u32, ___<u32>>;\nfn degree(g: &Graph, n: u32) -> usize {\n    g[&n].len()          // how many exits this station has\n}\n"] = "use std::collections::HashMap;\n// 駅 id -> 1 ホップ先の id たち (隣接リスト)\ntype Graph = HashMap<u32, ___<u32>>;\nfn degree(g: &Graph, n: u32) -> usize {\n    g[&n].len()          // この駅の出口の数\n}\n",
  ['use std::collections::HashMap;\nfn main() {\n    let mut count = HashMap::new();\n    count.insert("t7", 2);\n    *count.___("t4").or_insert(0) += 1;   // t4 is 1\n    println!("{:?}", count.get("t9"));    // None\n}\n'] = 'use std::collections::HashMap;\nfn main() {\n    let mut count = HashMap::new();\n    count.insert("t7", 2);\n    *count.___("t4").or_insert(0) += 1;   // t4 は 1\n    println!("{:?}", count.get("t9"));    // None\n}\n',
  ["use std::collections::HashMap; The :: walks the path. std is always there, no Cargo.toml line needed."] = "use std::collections::HashMap; の :: がパスをたどる。std は常にあるので、Cargo.toml に行を足す必要はない。",
  ['use std::error::Error;\nfn main() -> Result<(), ___<dyn Error>> {\n    let qty: i32 = "18".parse()?;   // ParseIntError fits\n    let text = std::fs::read_to_string("menu.txt")?;\n    println!("{qty} sets, {} bytes of menu", text.len());\n    Ok(())\n}\n'] = 'use std::error::Error;\nfn main() -> Result<(), ___<dyn Error>> {\n    let qty: i32 = "18".parse()?;   // ParseIntError も収まる\n    let text = std::fs::read_to_string("menu.txt")?;\n    println!("{qty} sets, {} bytes of menu", text.len());\n    Ok(())\n}\n',
  ['use std::fmt;\n// Receipt carries a lifetime; fmt does not need its name.\nimpl fmt::Display for Receipt<___> {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} paid {}", self.name, self.total)\n    }\n}\n'] = 'use std::fmt;\n// Receipt はライフタイムを持つ。fmt にはその名前は要らない。\nimpl fmt::Display for Receipt<___> {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} paid {}", self.name, self.total)\n    }\n}\n',
  ['use std::fmt;\n// Teach println!("{}") how to print an Order.\nimpl fmt::___ for Order {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} x{}", self.bun, self.qty)\n    }\n}\n'] = 'use std::fmt;\n// println!("{}") に Order の出力方法を教える。\nimpl fmt::___ for Order {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} x{}", self.bun, self.qty)\n    }\n}\n',
  ['use std::fmt;\nimpl fmt::___ for OrderError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "order failed")\n    }\n}\n'] = 'use std::fmt;\nimpl fmt::___ for OrderError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "order failed")\n    }\n}\n',
  ['use std::fs;\n// A missing menu file is a bug: stop with a message.\nlet menu = fs::read_to_string("menu.txt")\n    .___("menu.txt must exist");\n'] = 'use std::fs;\n// メニューファイルがないのはバグ: メッセージを出して止める。\nlet menu = fs::read_to_string("menu.txt")\n    .___("menu.txt must exist");\n',
  ["use std::num::ParseIntError;\n\n#[derive(Debug)]\n___ OrderError {\n    Empty,\n    BadQty(ParseIntError),\n}\n"] = "use std::num::ParseIntError;\n\n#[derive(Debug)]\n___ OrderError {\n    Empty,\n    BadQty(ParseIntError),\n}\n",
  ["use std::num::ParseIntError;\n// Hand any parse error straight back to the caller.\nfn cents(s: &str) -> Result<u32, ParseIntError> {\n    let n: u32 = s.parse()___;\n    Ok(n * 100)\n}\n"] = "use std::num::ParseIntError;\n// parse のエラーはそのまま呼び出し側に渡す。\nfn cents(s: &str) -> Result<u32, ParseIntError> {\n    let n: u32 = s.parse()___;\n    Ok(n * 100)\n}\n",
  ["use std::sync::Arc;\n// Arc: one receiver, many owners across threads.\n// The lock: only one cook holds the rail at a time.\nlet rx = Arc::new(___::new(rx));\nlet rx2 = Arc::clone(&rx);       // one clone per cook\n"] = "use std::sync::Arc;\n// Arc: 受信者は 1 つ、所有者はスレッドをまたいで多数。\n// 鍵: 一度にレールを握る料理人は 1 人だけ。\nlet rx = Arc::new(___::new(rx));\nlet rx2 = Arc::clone(&rx);       // 料理人 1 人につき clone 1 つ\n",
  ['use std::sync::RwLock;\nlet menu = RwLock::new(vec!["bun", "egg tart"]);\n// Many may look at once; only .write() has to wait.\nlet first = menu.___().unwrap()[0];\n'] = 'use std::sync::RwLock;\nlet menu = RwLock::new(vec!["bun", "egg tart"]);\n// 同時に何人でも見られる。待つのは .write() だけ。\nlet first = menu.___().unwrap()[0];\n',
  ["use std::sync::atomic::{AtomicUsize, Ordering};\nstatic SERVED: AtomicUsize = AtomicUsize::new(0);\n// No lock needed: add one in a single hardware step.\nSERVED.___(1, Ordering::SeqCst);\n"] = "use std::sync::atomic::{AtomicUsize, Ordering};\nstatic SERVED: AtomicUsize = AtomicUsize::new(0);\n// ロック不要: ハードウェアの 1 ステップで 1 を足す。\nSERVED.___(1, Ordering::SeqCst);\n",
  ['use std::sync::mpsc;\n// One pipe from till to kitchen: a sender and a receiver.\nlet (tx, rx) = mpsc::___();\ntx.send("egg tart").unwrap();\n'] = 'use std::sync::mpsc;\n// レジから厨房へのパイプ 1 本: 送信者と受信者。\nlet (tx, rx) = mpsc::___();\ntx.send("egg tart").unwrap();\n',
  ["use std::sync::mpsc;\ntype Job = Box<dyn FnOnce() + Send>;\n// one rail: many senders allowed, exactly one receiver\nlet (tx, rx) = mpsc::___::<Job>();\n"] = "use std::sync::mpsc;\ntype Job = Box<dyn FnOnce() + Send>;\n// レールは 1 本: 送信者は多数、受信者はちょうど 1 人\nlet (tx, rx) = mpsc::___::<Job>();\n",
  ['use std::thread;\n// The grill gets its own thread; the till keeps serving.\nlet grill = thread::___(|| {\n    println!("bun is toasting");\n});\ngrill.join().unwrap();\n'] = 'use std::thread;\n// グリルは自分のスレッドをもらう。レジは接客を続ける。\nlet grill = thread::___(|| {\n    println!("bun is toasting");\n});\ngrill.join().unwrap();\n',
  ['use std::time::Duration;\n// Steep the tea for 300 ms before pouring.\nthread::___(Duration::from_millis(300));\nprintln!("pour");\n'] = 'use std::time::Duration;\n// 注ぐ前に 300 ms お茶を蒸らす。\nthread::___(Duration::from_millis(300));\nprintln!("pour");\n',
  ["utf8.RuneCountInString counts code points. []rune(s) makes them indexable."] = "utf8.RuneCountInString はコードポイントを数えます。[]rune(s) ならインデックスで参照できます。",
  ["v is an any that holds a string. Take it out: s := v.(___)"] = "v は string を持つ any。取り出します: s := v.(___)",
  ["v, ok := m[k]. If ok is false, v is the zero value and the key was missing."] = "v, ok := m[k]。ok が false なら v はゼロ値で、キーは無かったということです。",
  ["v.(T) is a type assertion. s, ok := v.(T) never panics."] = "v.(T) は型アサーション。s, ok := v.(T) は決して panic しません。",
  ["var count [26]int\nfor _, c := range a {\n    count[c-'a']___          // add\n}\nfor _, c := range b {\n    count[c-'a']--           // remove\n}\n"] = "var count [26]int\nfor _, c := range a {\n    count[c-'a']___          // 加算\n}\nfor _, c := range b {\n    count[c-'a']--           // 減算\n}\n",
  ["var err error\nif err != ___ {\n    return err\n}\n"] = "var err error\nif err != ___ {\n    return err\n}\n",
  ['var floors map[string]int      // nil: read ok, write panics\nfloors = ___(map[string]int)\nfloors["Sogo"] = 1\n'] = 'var floors map[string]int      // nil: 読みはOK、書きは panic\nfloors = ___(map[string]int)\nfloors["Sogo"] = 1\n',
  ['var frames ___          // length is part of the type\nframes[0] = "muffin"\n'] = 'var frames ___          // 長さは型の一部\nframes[0] = "muffin"\n',
  ["var memo = map[int]int{}\n\nfunc fib(n int) int {\n    if v, ok := memo[n]; ___ {\n        return v            // seen before\n    }\n"] = "var memo = map[int]int{}\n\nfunc fib(n int) int {\n    if v, ok := memo[n]; ___ {\n        return v            // 計算済み\n    }\n",
  ["var mu sync.RWMutex\nmu.___()                // readers share\nn := count\nmu.RUnlock()\n"] = "var mu sync.RWMutex\nmu.___()                // 読み手は共有\nn := count\nmu.RUnlock()\n",
  ["var mu sync.___\nmu.Lock()\ncount++\nmu.Unlock()\n"] = "var mu sync.___\nmu.Lock()\ncount++\nmu.Unlock()\n",
  ["var n int              // zero value\nfmt.Println(n)         // prints ___\n"] = "var n int              // ゼロ値\nfmt.Println(n)         // ___ を出力\n",
  ["var n int with no assignment. What is n?"] = "代入なしの var n int。n の値は？",
  ["var name type = value. Outside a function := is a compile error."] = "var 名前 型 = 値。関数の外で := はコンパイルエラーです。",
  ["var once sync.___\nfunc grill() {\n    once.Do(warm)      // warm runs one time\n}\n"] = "var once sync.___\nfunc grill() {\n    once.Do(warm)      // warm は一度だけ実行\n}\n",
  ["var order Order\nerr := json.___(b, &order)   // pointer!\n"] = "var order Order\nerr := json.___(b, &order)   // ポインタ！\n",
  ["var p *Order = nil\nvar i any = p\nfmt.Println(i == nil)   // prints ___\n"] = "var p *Order = nil\nvar i any = p\nfmt.Println(i == nil)   // ___ を出力\n",
  ['var p ___Order         // address of an Order\np = &Order{Item: "set"}\n'] = 'var p ___Order         // Order のアドレス\np = &Order{Item: "set"}\n',
  ["var prev *ListNode\ncur := head\nfor cur != nil {\n    next := cur.Next      // save before we cut it\n    cur.Next = ___\n    prev, cur = cur, next\n}\n"] = "var prev *ListNode\ncur := head\nfor cur != nil {\n    next := cur.Next      // 切る前に保存\n    cur.Next = ___\n    prev, cur = cur, next\n}\n",
  ["var r ___ = '灣'        // one code point\nfmt.Println(r)          // 28771\n"] = "var r ___ = '灣'        // コードポイントひとつ\nfmt.Println(r)          // 28771\n",
  ["var re *RefundError\nif errors.___(err, &re) {      // typed match\n    pay(re.Amount)\n}\n"] = "var re *RefundError\nif errors.___(err, &re) {      // 型で一致\n    pay(re.Amount)\n}\n",
  ['var v any = "muffin"\ns := v.(___)              // panics if v is not one\ns2, ok := v.(string)      // safe form\n'] = 'var v any = "muffin"\ns := v.(___)              // v が string でなければ panic\ns2, ok := v.(string)      // 安全な形\n',
  ["var wg sync.___\nwg.Add(2)\ngo cook(&wg)\nwg.Wait()\n"] = "var wg sync.___\nwg.Add(2)\ngo cook(&wg)\nwg.Wait()\n",
  ["vec![18, 22, 25] is the literal form. Vec::new() makes an empty one. Index with [0] like Go."] = "vec![18, 22, 25] がリテラルの形。Vec::new() は空のものを作る。添字は Go と同じく [0]。",
  ['visited := map[string]___{}\nqueue := []string{"Causeway Bay"}\nvisited["Causeway Bay"] = true\n'] = 'visited := map[string]___{}\nqueue := []string{"Causeway Bay"}\nvisited["Causeway Bay"] = true\n',
  ["wg.Add(1) per worker, or wg.Add(3) once. Pass &wg: a WaitGroup must not be copied."] = "worker ごとに wg.Add(1)、または一度に wg.Add(3)。&wg を渡す: WaitGroup はコピー禁止。",
  ["where T: Display, reads the same as <T: Display> but stays legible with many bounds."] = "where T: Display, は <T: Display> と同じ意味だが、境界が多くても読みやすい。",
  ["while left > 0 { } Prints 2 then 0. continue jumps to the next check, break leaves."] = "while left > 0 { } は 2、そして 0 を出力。continue は次の判定へ飛び、break は抜ける。",
  ["who returns a borrow of self. Write the return type with no lifetime at all."] = "who は self の借用を返す。ライフタイムを一切書かずに戻り値の型を書いて。",
  ["x := 1\ndefer fmt.Println(x)    // prints ___ at the end\nx = 2\n"] = "x := 1\ndefer fmt.Println(x)    // 最後に ___ を出力\nx = 2\n",
  ["{} uses Display. {:?} uses Debug. {n} reads a variable by name. Three muffins, printed."] = "{} は Display、{:?} は Debug を使う。{n} は変数を名前で読む。マフィン 3 個、出力完了。",
  ["|x| x * 2 is a closure. It captures nothing here; map calls it for every &i32."] = "|x| x * 2 はクロージャ。ここでは何もキャプチャしない。map が &i32 ごとに呼ぶ。",
  ["~T means 'underlying type T'. | joins the choices. See constraints.Ordered."] = "~T は「基底型が T」の意味。| で選択肢を繋ぎます。constraints.Ordered を参照。",
}
